import {tools,categories,popular,findTool} from './catalog.js';
import {$,$$,el,icon,url,field,read,action,copy,status,setupStatus,notice} from './core.js';
const search=$('#search');
function searchTools(query){const words=query.toLowerCase().split(/\s+/).filter(Boolean);return tools.filter(t=>words.every(w=>`${t.title} ${t.description} ${t.category}`.toLowerCase().includes(w)))}
if(search){search.addEventListener('input',()=>{const box=$('#search-results');box.replaceChildren();box.hidden=!search.value.trim();if(box.hidden)return;const results=searchTools(search.value).slice(0,10);for(const t of results){const a=el('a',{href:url(t.path)}),g=el('span');g.innerHTML=icon(t.icon);a.append(g,el('span',{},[el('strong',{text:t.title}),el('small',{text:t.category})]));box.append(a)}if(!results.length)box.append(el('p',{class:'empty',text:'No matching tools. Try “PDF”, “resume” or “image”.'}))});search.addEventListener('keydown',e=>{if(e.key==='Escape')$('#search-results').hidden=true;if(e.key==='Enter')$('#search-results a')?.click()});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#search-results').hidden=true});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();search.focus()}})}
const slug=document.body.dataset.tool;
if(slug){const t=findTool(slug),root=$('#workspace');try{let mod;if(t.category==='calculators'||['freelance-rate','timesheet'].includes(slug))mod=await import('./calculators.js');else if(t.category==='work')mod=await import('./work.js');else if(t.category==='images'||slug==='application-document-prep')mod=await import('./images.js');else if(['document-editor','docx-viewer','csv-cleaner'].includes(slug))mod=await import('./editor.js');else mod=await import('./pdf.js');await mod.mount(root,slug)}catch(e){root.append(el('p',{class:'status error',text:'This workspace could not start. Reload the page and try again.'}));console.error(e)}}
if(document.body.dataset.page==='request'){const root=$('#workspace'),f=el('div',{class:'fields'});f.append(field('request-type','Request type','select','New tool',{options:['New tool','Improve existing tool']}),field('area','Area','select','Documents',{options:['Work','Documents','Images','Calculators','Other']}),field('title','What do you need?','text','',{full:true,maxlength:120}),field('problem','What are you trying to do?','textarea','',{full:true,maxlength:3000}),field('existing','Existing tool (if applicable)'),field('frequency','Frequency','select','Occasionally',{options:['Frequently','Occasionally','Once/rarely']}));const out=el('textarea',{id:'request-output',rows:8,'aria-label':'Prepared request'}),actions=el('div',{class:'actions'});actions.append(action('Prepare request',()=>{if(!read('title')||!read('problem'))throw Error('Add a short title and explain the task.');out.value=`${read('request-type')}: ${read('title')}\n\nArea: ${read('area')}\nTask: ${read('problem')}\nExisting tool: ${read('existing')||'None'}\nFrequency: ${read('frequency')}`},true),action('Copy request',()=>{if(!out.value)throw Error('Prepare a request first.');return copy(out.value)}));root.append(f,actions,out);notice(root,'Preparation stays in your browser. GitHub submission opens another website and requires a GitHub account. Its terms and privacy policy apply. Do not include private files or personal information.');const config=await fetch(url('site-config.json')).then(r=>r.json());if(config.githubIssuesURL){const a=el('a',{class:'button',text:'Submit via GitHub',target:'_blank',rel:'noopener'});a.addEventListener('click',e=>{if(!out.value){e.preventDefault();status('Prepare a request first.',true);return}const u=new URL(config.githubIssuesURL);u.searchParams.set('title',read('title'));u.searchParams.set('body',out.value);a.href=u.href});a.href=config.githubIssuesURL;root.append(a)}else notice(root,'GitHub submission will be available when the site owner connects the public issue tracker. You can prepare and copy your request now.');setupStatus(root)}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'search_alltoolforest',description:'Find available AllToolForest tools by task; does not navigate or process files.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({query})=>{if(typeof query!=='string'||!query.trim()||query.length>100)throw Error('Enter a search phrase between 1 and 100 characters.');if(search){search.value=query;search.dispatchEvent(new Event('input'))}return searchTools(query).slice(0,10).map(t=>({title:t.title,url:url(t.path)}))}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
